mapper.select:
SELECT *
FROM public.nocode_application_object_follow
WHERE application_id = #{app}
AND object_id = #{object}
AND deleted = 0

mapper.update:
UPDATE public.nocode_application_object_follow
SET enabled = #{enabled}, lock_version = lock_version + 1, updater = #{actor}, update_time = clock_timestamp()
WHERE application_id = #{app}
AND object_id = #{object}
AND lock_version = #{expected}
AND deleted = 0

mapper.select:
SELECT count(*)
FROM public.nocode_handling_request
WHERE object_id = #{object}
AND deleted = 0
AND status IN
#{state}
